'app\',\'%offline%\',\'ebo\')) ; CREATE OR REPLACE TABLE MapleMonk.Zouk_Power_Potli_Data AS select * from `MapleMonk.zouk_Secondary_sales_consolidated` where lower(PRODUCT_CATEGORY) like \'%power%\' ; CREATE OR REPLACE TABLE MapleMonk.zouk_Luggage_Secondary_PandL AS SELECT * FROM `MapleMonk.zouk_secondary_pandl` WHERE LOWER(COLLECTION) like \'%luggage%\' ; CREATE OR REPLACE TABLE MapleMonk.zouk_Store_AOV_Achievement AS WITH weekly_aov AS ( SELECT Store_Code, source, DATE_TRUNC(order_date, WEEK(MONDAY)) AS week_start, SUM(selling_price) / COUNT(DISTINCT order_id) AS AOV FROM `maplemonk.zouk_sales_consolidated_offline` WHERE order_date IS NOT NULL and lower(ORDER_STATUS) not like \'%cancel%\' and lower(FINAL_MARKETPLACE) like \'ebo\' GROUP BY 1,2,3 ) SELECT Store_Code, Source AS Store_Name, week_start, AOV, 2400 AS target_aov, CASE WHEN AOV >= 2400 THEN 24 ELSE 0 END AS runs FROM weekly_aov ; Create or replace table maplemonk.zouk_Sales_Cost_Source_offline as WITH Sessions AS ( SELECT PARSE_DATE(\'%Y-%m-%d\', date_string) AS Date, UPPER(m.store_name) AS marketing_channel, \"SHOPIFY POS\" AS marketplace, SAFE_CAST(engagers_group_count AS INT64) AS Walkins, SAFE_CAST(engagers_count AS INT64) AS Footfall, 0 AS Sessions FROM `MapleMonk.zouk_db_get_consolidated_day` d LEFT JOIN `Maplemonk.zouk_ebo_Mapping_sheet` m ON TRIM(LOWER(d.store_id)) = TRIM(LOWER(m.store_id)) UNION ALL SELECT DATE(SAFE_CAST(time AS DATETIME)) AS Date, UPPER(m.store_name) AS marketing_channel, \"SHOPIFY POS\" AS marketplace, 0 AS Walkins, sum(SAFE_CAST(passengerFlow AS INT64)) AS Footfall, 0 AS Sessions FROM `MapleMonk.Zouk_get_many_shops_passenger_indicator_data` d LEFT JOIN `Maplemonk.zouk_ebo_Mapping_sheet` m ON TRIM(LOWER(d.store_id)) = TRIM(LOWER(m.store_id)) GROUP BY 1,2 UNION ALL SELECT PARSE_DATE(\'%Y-%m-%d\', d.Date) AS Date, UPPER(m.store_name) AS marketing_channel, \"SHOPIFY POS\" AS marketplace, 0 AS Walkins, SUM(SAFE_CAST(d.total_count AS INT64)) AS Footfall, 0 AS Sessions FROM ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER ( PARTITION BY Date, store_code ORDER BY Date DESC ) AS rn FROM `MapleMonk.Zouk_ext_analytics` ) WHERE rn = 1 ) d LEFT JOIN `Maplemonk.zouk_ebo_Mapping_sheet` m ON TRIM(LOWER(d.store_code)) = TRIM(LOWER(m.store_id)) GROUP BY 1, 2 UNION ALL SELECT PARSE_DATE(\'%m/%d/%Y\', date) AS Date, UPPER(store_name) AS marketing_channel, \"SHOPIFY POS\" AS marketplace, SUM(SAFE_CAST(Walkins AS INT64)) AS Walkins, SUM(SAFE_CAST(Footfall AS INT64)) AS Footfall, 0 AS Sessions FROM `MapleMonk.EBO_Footfall_Walkins_Form_Responses_1` WHERE lower(store_name) like any (\'%koramangala%\',\'%lulu_bangalore%\',\'%vega_city%\',\'%mohali_walk%\',\'%tribeca%\',\'%citadel%\',\'%hubbali%\',\'%dsl_virtue%\') GROUP BY 1, 2, 3 ), SPend as ( select date as marketing_date, coalesce(offline_channel,case when lower(campaign_name) like \'%seawoods%\' then \'Zouk Nexus Seawoods Mall Store\' when lower(campaign_name) like \'%koramangala%\' then \'Zouk Koramangala Store\' end )as channel, \'SHOPIFY POS\' as Marketplace, \'EBO\' as FInal_Marketplace, sum(ifnull(spend,0))spend, sum(ifnull(clicks,0)) as clicks, sum(ifnull(impressions,0)) as impressions, sum(ifnull(conversions,0)) as conversions from maplemonk.zouk_MARKETING_CONSOLIDATED mc left join ( select concat(\'\',LOCATION_ID,\'\') as LOCATION_ID ,channel as offline_channel from MAPLEMONK.APP_ID_MAPPING qualify row_number() over (partition by LOCATION_ID order by 1) = 1 and LOCATION_ID is not null )li ON LOWER(mc.CAMPAIGN_NAME) LIKE CONCAT(\'%\', LOWER(li.LOCATION_ID), \'%\') where lower(campaign_name) like \'%offline%\' group by 1,2,3 ),returnsales as ( select cast(return_date as date) return_date ,marketing_channel ,case when lower(final_marketplace) like any (\'%amazon%\') then \'AMAZON\' when lower(final_marketplace) like any (\'%shopify%\') then \'SHOPIFY\' else upper(final_marketplace) end as marketplace ,sum(total_return_amount) TOTAL_RETURN_AMOUNT ,sum(total_return_amount_excl_tax) TOTAL_RETURN_AMOUNT_EXCL_TAX ,sum(total_returned_quantity) TOTAL_RETURNED_QUANTITY from maplemonk.zouk_RETURNS_CONSOLIDATED where lower(ifnull(final_marketplace,\'\')) like any (\'%offline%\',\'%ebo%\') group by 1,2,3 order by 1 desc ), orders as ( select cast(FI.order_date as date) Date ,upper(final_marketplace) Marketplace ,upper(FI.Source) marketing_CHANNEL ,ifnull(sum(ifnull(FI.SELLING_PRICE,0)),0) Total_Sales ,ifnull(sum(ifnull(FI.SELLING_PRICE,0)),0) - ifnull(sum(case when lower(FI.order_status) in (\'cancelled\') then ifnull(FI.SELLING_PRICE,0) else 0 end),0) TOTAL_SALES_EXCL_CANCL ,count(distinct FI.order_id) Total_Orders ,count(distinct FI.order_id) - count(distinct case when lower(FI.order_status) in (\'cancelled\') then FI.order_id end) Orders_EXCL_CANCL ,count(distinct(case when lower(FI.new_customer_flag) = \'new\' then FI.order_id end)) as New_Customer_Orders ,count(distinct(case when lower(FI.new_customer_flag) = \'new\' then FI.order_id end)) - count(distinct(case when lower(FI.new_customer_flag) = \'new\' and lower(FI.order_status) in (\'cancelled\') then FI.order_id end)) as New_Customer_Orders_EXCL_CANCL ,count(distinct(case when lower(FI.new_customer_flag) = \'new\' then FI.customer_id_final end)) as Total_New_Customers ,count(distinct(case when lower(FI.new_customer_flag) = \'new\' then FI.customer_id_final end)) - count(distinct(case when lower(FI.new_customer_flag) = \'new\' and lower(FI.order_status) in (\'cancelled\') and FI.return_flag = 0 then FI.customer_id_final end)) New_Customers_EXCL_CANCL ,count(distinct FI.customer_id_final) as TOTAL_Unique_Customers ,(count(distinct FI.customer_id_final) - count(distinct case when lower(FI.order_status) in (\'cancelled\') then FI.customer_id_final end)) as Unique_Customers_EXCL_CANCL ,count(distinct(case when lower(FI.new_customer_flag) = \'repeat\' then FI.customer_id_final end)) as Repeat_Customers ,(count(distinct(case when lower(FI.new_customer_flag) = \'repeat\' then FI.customer_id_final end)) - count(distinct(case when lower(FI.new_customer_flag) = \'repeat\' and lower(FI.order_status) in (\'cancelled\') and FI.return_flag = 0 then FI.customer_id_final end))) Repeat_Customers_EXCL_CANCL ,ifnull(sum(FI.discount),0) TOTAL_DISCOUNT ,(ifnull(sum(FI.discount),0) - ifnull(sum(case when lower(FI.order_status) in (\'cancelled\') then FI.discount end),0)) TOTAL_DISCOUNT_EXCL_CANCL ,ifnull(sum(FI.tax),0) TOTAL_TAX ,(ifnull(sum(FI.tax),0) - ifnull(sum(case when lower(FI.order_status) in (\'cancelled\') then FI.tax end),0)) TAX_EXCL_CANCL ,ifnull(sum(FI.shipping_price),0) TOTAL_SHIPPING_PRICE ,(ifnull(sum(FI.shipping_price),0) - ifnull(sum(case when lower(FI.order_status) in (\'cancelled\') then FI.shipping_price end),0)) SHIPPING_PRICE_EXCL_CANCL ,ifnull(sum(case when lower(FI.new_customer_flag) = \'new\' then FI.discount end),0) as New_Customer_Discount ,(ifnull(sum(case when lower(FI.new_customer_flag) = \'new\' then FI.discount end),0) - ifnull(sum(case when lower(FI.new_customer_flag) = \'new\' and lower(order_status) in (\'cancelled\') then FI.discount end),0)) as New_Customer_Discount_EXCL_CANCL ,ifnull(sum(FI.quantity),0) TOTAL_QUANTITY ,(ifnull(sum(FI.quantity),0) - ifnull(sum(case when lower(FI.order_status) in (\'cancelled\') then FI.quantity end),0)) QUANTITY_EXCL_CANCL ,ifnull(sum(case when FI.return_flag=1 then FI.quantity end),0) as Return_Quantity ,ifnull(sum(case when FI.return_flag=1 then ifnull(FI.SELLING_PRICE,0) end),0) as Return_Value ,count(distinct case when lower(order_status) in (\'cancelled\') then order_id end) Cancelled_Orders ,count(distinct case when lower(order_status) not in (\'cancelled\') and return_flag=0 then order_id end) Net_Orders ,count(distinct case when lower(order_status) in (\'delivered\') then order_id end) Delivered_Orders ,count(distinct case when lower(order_status) in (\'returned\',\'rto\') then order_id end) Returned_Orders ,count(distinct case when dispatch_date is not null and lower(order_status) not in (\'cancelled\') then order_id end) Dispatched_Orders ,count(distinct case when lower(order_status) in (\'shipped\',\'printed\',\'confirmed\',\'returned\',\'ready to dispatch\') then order_id end) Realised_Orders ,ifnull(sum(case when lower(order_status) in (\'delivered\') then ifnull(FI.SELLING_PRICE,0)-ifnull(FI.TAX,0) end),0) Delivered_Revenue ,ifnull(sum(case when lower(order_status) in (\'returned\',\'rto\') then ifnull(FI.SELLING_PRICE,0)-ifnull(FI.TAX,0) end),0) Returned_Revenue ,ifnull(sum(case when dispatch_date is not null and lower(order_status) not in (\'cancelled\') then ifnull(FI.SELLING_PRICE,0) end),0) Dispatched_Revenue ,ifnull(sum(case when lower(order_status) in (\'shipped\',\'printed\',\'confirmed\',\'returned\',\'ready to dispatch\') then ifnull(FI.SELLING_PRICE,0) end),0) Realised_Revenue ,count(case when date_trunc(acquisition_date, month)>=DATE_ADD(DATE_TRUNC(order_date, MONTH), INTERVAL -3 MONTH) and date_trunc(acquisition_date, month)<date_trunc(order_date, month) then customer_id_final end) L3M_Customers_Retained ,count(case when date_trunc(acquisition_date, month)>=DATE_ADD(DATE_TRUNC(order_date, MONTH), INTERVAL -6 MONTH) and date_trunc(acquisition_date, month)<date_trunc(order_date, month) then customer_id_final end) L6M_Customers_Retained ,count(case when date_trunc(acquisition_date, month)>=DATE_ADD(DATE_TRUNC(order_date, MONTH), INTERVAL -12 MONTH) and date_trunc(acquisition_date, month)<date_trunc(order_date, month) then customer_id_final end) L12M_Customers_Retained ,sum(case when lower(FI.new_customer_flag) = \'repeat\' then ifnull(FI.selling_price,0) end) Repeat_Customer_Revenue ,count(distinct case when lower(FI.payment_mode) in (\'cod\') then FI.order_id end) as COD_Orders from maplemonk.zouk_SALES_CONSOLIDATED FI where lower(MARKETPLACE_SEGMENT) like any (\'%offline%\',\'%ebo%\') group by 1,2,3 ) select coalesce(fi.Date, SC.date,rs.return_date,sp.marketing_date) as date, upper(coalesce(fi.marketplace,RS.marketplace, SC.marketplace,sp.marketplace)) as Marketplace, upper(coalesce(fi.marketing_channel,RS.marketing_channel, SC.marketing_channel,sp.channel)) as Marketing_Channel, Total_Sales, TOTAL_SALES_EXCL_CANCL, SC.sessions, SC.walkins, SC.Footfall, Total_Orders, Orders_EXCL_CANCL, New_Customer_Orders, New_Customer_Orders_EXCL_CANCL, Total_New_Customers, New_Customers_EXCL_CANCL, TOTAL_Unique_Customers, Unique_Customers_EXCL_CANCL, Repeat_Customers, Repeat_Customers_EXCL_CANCL, TOTAL_DISCOUNT, TOTAL_DISCOUNT_EXCL_CANCL, TOTAL_TAX, TAX_EXCL_CANCL, TOTAL_SHIPPING_PRICE, SHIPPING_PRICE_EXCL_CANCL, New_Customer_DISCOUNT, New_Customer_Discount_EXCL_CANCL, TOTAL_QUANTITY, QUANTITY_EXCL_CANCL, RS.TOTAL_RETURNED_QUANTITY as Return_Quantity, RS.TOTAL_RETURN_AMOUNT as Return_Value, Cancelled_Orders, Net_Orders, Delivered_Orders, Delivered_Revenue, Dispatched_Orders, Dispatched_Revenue, Realised_Orders, Realised_Revenue, spend as marketing_spend, 0 as Brand_Spend, COD_Orders, Repeat_Customer_Revenue, conversions as ad_conversions, impressions as ad_impressions, clicks as ad_clicks, 0 ad_sales from orders FI full outer join returnsales RS on RS.return_date = FI.date and lower(RS.marketing_Channel) = lower(FI.marketing_Channel) and lower(RS.marketplace)=lower(FI.marketplace) full outer join SESSIONS SC on coalesce(FI.Date,RS.return_date)=SC.Date and lower(coalesce(FI.Marketing_Channel,RS.marketing_Channel))=lower(SC.Marketing_Channel) and lower(coalesce(FI.marketplace,RS.marketplace))=lower(SC.Marketplace) full outer join SPend sp on lower(sp.channel) = lower(coalesce(FI.Marketing_Channel,RS.marketing_Channel,SC.Marketing_Channel)) and sp.marketing_date = coalesce(FI.Date,RS.return_date,SC.Date) and lower(coalesce(FI.marketplace,RS.marketplace,SC.Marketplace)) = lower(sp.marketplace) ;",
